  const retry=failed&&financial?.updateStatus?.canRetry===true&&rangeStart&&rangeEnd?`<form method="post" action="/overview/financial-retry"><input type="hidden" name="storeId" value="${esc(selectedStoreId||'')}"><input type="hidden" name="periodStart" value="${esc(rangeStart)}"><input type="hidden" name="periodEnd" value="${esc(rangeEnd)}"><button class="outline-button" type="submit">Повторить расчёт</button></form>`:'';
  const updateNotice=updating?`<div class="financial-calculation-state" aria-live="polite" aria-busy="true"><strong>${updateStatus==='pending'?'Обновление поставлено в очередь':'Обновляем результат'}</strong><p>Пока показываем последнюю опубликованную сумму. Она заменится только после успешной публикации нового расчёта.</p><p class="financial-calculation-poll-note" data-financial-poll-note hidden>Автообновление остановлено. Проверьте результат вручную.</p><button type="button" class="outline-button financial-calculation-refresh" data-financial-refresh-now>Обновить сейчас</button></div>`:failed?`<div class="financial-calculation-state" aria-live="polite"><strong>Не удалось обновить расчёт</strong><p>Последняя опубликованная сумма сохранена. Автоматические повторы остановлены.</p>${retry}</div>`:'';
