  const renderedItems=items.map(item=>{const amount=item.metric?.absoluteValue??item.metric?.value;return`<article class="design-attention-row"><span class="signal-mark ${item.severity==='danger'?'danger':''}">!</span><div><strong>${esc(titles[item.kind]||item.title||item.kind||'Ситуация')}</strong>${amount!==undefined?`<p class="negative">${overviewMoney(amount)}</p>`:''}${item.productId?`<small>Товар: ${esc(item.productId)}</small>`:''}</div>${overviewDevelopment('Подробности в разработке')}</article>`;}).join('');
