function checkpointsOverviewPanel(){return`<section class="design-bottom-panel checkpoints-panel"><h2>КОНТРОЛЬНЫЕ ТОЧКИ</h2><div class="development-timeline"><span></span><div><strong>Контрольные точки</strong><p>Планирование проверок рекламы и поставок</p>${overviewDevelopment()}</div></div><div class="design-section-footer"><span>Все контрольные точки</span>${overviewDevelopment()}</div></section>`;}
function liveOverviewPage(user,stores,state,{selectedStoreId,selectedWeek,selectedPeriodStart,selectedPeriodEnd}={}){
  const selected=stores.find(store=>store.id===(selectedStoreId||state.store?.id))||stores[0],ordered=[selected,...stores.filter(store=>store!==selected)];
  const periodStart=state.financial?.requestedPeriod?.start||selectedPeriodStart||selectedWeek||null,periodEnd=state.financial?.requestedPeriod?.end||selectedPeriodEnd||periodStart;
  return frame({...user,stores:ordered},'/overview',`<section class="live-overview design-overview"><div class="design-overview-top">${financialOverviewPanel(state.financial,{selectedStoreId:selected.id,selectedWeek,selectedPeriodStart,selectedPeriodEnd})}${operationalOverviewPanel(state.operational)}${situationsOverviewPanel(state.situations)}</div><div class="design-overview-bottom">${checksOverviewPanel()}${checkpointsOverviewPanel()}</div></section>`,ordered,{periodStart,periodEnd});
}
export function overviewPage(user, stores=user.stores, state=null, options={}) {
  const availableStores=Array.isArray(stores)?stores:[{name:'Дом и уют',status:'active',connected:true,demo:true}];
  if(state)return liveOverviewPage(user,availableStores,state,options);
  const selected=availableStores.find(store=>store.id===options.selectedStoreId)||availableStores[0];
  const ordered=selected?[selected,...availableStores.filter(store=>store!==selected)]:availableStores;
  if(selected?.demo===true)return populatedOverviewPage({...user,stores:ordered});
  return emptyOverviewPage(user,ordered);
}
